#!/usr/bin/env python3
"""Slupecki test for ternary cell sets: size of the unary closure generated by each cell set
(27 = all unary maps = functionally complete, given a surjective binary cell). Writes results/cell_sets.json."""
import itertools, json, sys
V = (0, 1, 2)                      # -, 0, +
STI = lambda a: 2 - a
NTI = lambda a: 2 if a == 0 else 0
PTI = lambda a: 0 if a == 2 else 2
INC = lambda a: (a + 1) % 3
DEC = lambda a: (a - 1) % 3
TNAND = lambda a, b: 2 - min(a, b)
TNOR = lambda a, b: 2 - max(a, b)
MIN = lambda a, b: min(a, b); MAX = lambda a, b: max(a, b)
C1 = lambda: 1
CELLS = {"STI": STI, "NTI": NTI, "PTI": PTI, "INC": INC, "DEC": DEC, "TNAND": TNAND, "TNOR": TNOR, "MIN": MIN, "MAX": MAX, "C1": C1}
def unary_closure(names):
    fs = set([tuple(V)])             # identity
    for n in names:
        if CELLS[n].__code__.co_argcount == 0: fs.add((1, 1, 1))
    changed = True
    while changed:
        changed = False
        for n in names:
            f = CELLS[n]; k = f.__code__.co_argcount
            new = set()
            for u in list(fs):
                if k == 1: new.add(tuple(f(u[x]) for x in V))
                elif k == 2:
                    for v in fs: new.add(tuple(f(u[x], v[x]) for x in V))
            if not new <= fs: fs |= new; changed = True
    return len(fs)
SETS = [["STI", "NTI", "PTI", "TNAND", "TNOR"], ["MIN", "MAX", "NTI", "PTI"], ["TNAND", "C1"],
        ["STI", "NTI", "PTI", "TNAND", "TNOR", "C1"], ["STI", "NTI", "PTI", "TNAND", "TNOR", "INC"], ["TNAND", "INC"], ["MIN", "MAX", "INC"],
        ["STI", "NTI", "PTI", "TNAND", "TNOR", "C1", "INC", "DEC"]]
out = {}
for s in SETS:
    n = unary_closure(s); out["+".join(s)] = {"unary_maps": n, "complete": n == 27}
    print(f"{'{'+', '.join(s)+'}':48s} {n:3d} {'yes' if n == 27 else 'no'}")
json.dump(out, open((sys.argv[1] if len(sys.argv) > 1 else "results") + "/cell_sets.json", "w"), indent=1)
